// Validates AI reply against the real action_status; falls back to a safe template if needed.
// Items arrive from AI Response Generator (success/error output) or directly from "Branch Succeeded?" false output (branch error).
const direct = !!($json && $json.ticket_id !== undefined && $json.output === undefined && $json.error === undefined);
let r;
if (direct) r = $json;
else { try { r = $('Branch Succeeded?').item.json; } catch (e) { try { r = $('Branch Succeeded?').all(0)[$itemIndex].json; } catch (e2) { r = $json; } } }

const branchFailed = r.execution_status === 'Failed';
const rawOut = (!direct && $json) ? $json.output : undefined;
const out = (rawOut && typeof rawOut === 'object') ? rawOut : {};
const MIN_LEN = 20;
let subject = typeof out.subject === 'string' ? out.subject.trim() : '';
let message = typeof out.message === 'string' ? out.message.trim() : '';
const claimsCompleted = out.claims_action_completed === true;
const issues = [];

if (branchFailed) {
  issues.push('Branch processing error; AI reply skipped');
} else {
  if ($json && $json.error) issues.push('AI response generation failed: ' + (typeof $json.error === 'string' ? $json.error : ($json.error.message || JSON.stringify($json.error))));
  if (!direct && !$json.error && (rawOut === undefined || rawOut === null || typeof rawOut !== 'object')) issues.push('AI response empty or not an object');
  if (out.subject === undefined || out.subject === null) issues.push('subject missing');
  else if (typeof out.subject !== 'string') issues.push('subject is not a string');
  else if (subject.length === 0) issues.push('subject empty');
  else if (subject.length < MIN_LEN) issues.push('subject too short (' + subject.length + ' < ' + MIN_LEN + ' chars)');
  if (out.message === undefined || out.message === null) issues.push('message missing');
  else if (typeof out.message !== 'string') issues.push('message is not a string');
  else if (message.length === 0) issues.push('message empty');
  else if (message.length < MIN_LEN) issues.push('message too short (' + message.length + ' < ' + MIN_LEN + ' chars)');
  if (typeof out.claims_action_completed !== 'boolean') issues.push('claims_action_completed missing or not boolean');
  const lower = message.toLowerCase();
  if (r.troubleshooting_context) {
    const hasUpdate = lower.includes('update');
    const hasRestart = lower.includes('restart') || lower.includes('reboot');
    const hasRetry = lower.includes('retry') || lower.includes('try again') || lower.includes('re-try') || lower.includes('try starting') || lower.includes('try it again');
    if (!(hasUpdate && hasRestart && hasRetry)) issues.push('reply does not contain all troubleshooting steps');
  }
  const success = r.action_status === 'simulated_success';
  const claims = ['has been cancelled', 'has been canceled', 'have cancelled', 'have canceled', 'has been refunded', 'have refunded', 'refund has been processed', 'successfully cancel', 'successfully refund',
    'is now cancelled', 'is now canceled', 'was refunded', 'was cancelled', 'was canceled', 'refunded your', 'i have cancelled', 'i have canceled', 'i cancelled', 'i canceled', 'we cancelled', 'we canceled',
    'your subscription is cancelled', 'your subscription is canceled', 'we have processed the refund', 'we have processed your refund', 'we have processed a', 'processed a full refund', 'refund is on its way',
    'refund has been issued', 'we have issued', "we've cancelled", "we've canceled", "we've refunded", "we've processed", 'cancellation is complete', 'cancellation has been processed', 'refund is complete', 'money has been returned'];
  if (!success && claims.some(c => lower.includes(c))) issues.push('reply claims success but action_status is ' + r.action_status);
  if (!success && claimsCompleted) issues.push('claims_action_completed is true but action_status is ' + r.action_status);
  const leaks = ['action_status', 'action_type', 'matching_subscription', 'simulated', 'workflow', 'system prompt', 'sub_test_'];
  if (leaks.some(c => lower.includes(c))) issues.push('reply exposes internal details');
}

const actionStatus = branchFailed ? 'requires_review' : r.action_status;

function fallback() {
  const lines = {
    simulated_success: 'Thanks for reaching out. We have taken care of your request. If anything still looks wrong, just reply to this email.',
    not_executed: 'Thanks for reaching out. Unfortunately we could not complete this request automatically. Please reply with more details and our team will help.',
    requires_review: 'Thanks for reaching out. A support specialist is reviewing your request and will get back to you shortly.',
    queued: 'Thanks for reaching out. Your message has been passed to our support team and they will reply soon.'
  };
  let body = lines[actionStatus] || lines.requires_review;
  if (r.troubleshooting_context && actionStatus === 'simulated_success') body = 'Thanks for reaching out, and sorry for the trouble. Please try these steps: 1) update the PulseFit app to the latest version, 2) restart your device, 3) open the app and retry. If the problem continues, just reply to this email.';
  return { subject: 'Re: ' + (r.subject || 'Your request') + ' - PulseFit Support', message: 'Hi,' + String.fromCharCode(10, 10) + body + String.fromCharCode(10, 10) + 'PulseFit Support' };
}

let source = 'ai';
if (issues.length) { const f = fallback(); subject = f.subject; message = f.message; source = 'fallback'; }

// Execution status: Success | Partial | Failed
const errorParts = [];
if (r.classification_note) errorParts.push(r.classification_note);
let executionStatus;
if (branchFailed) { executionStatus = 'Failed'; errorParts.push(r.error_message || 'Branch processing error'); }
else if (source === 'fallback') { executionStatus = 'Partial'; errorParts.push('Fallback reply used: ' + issues.join('; ')); }
else executionStatus = 'Success';
const errorMessage = errorParts.length ? errorParts.join(' | ') : null;

const finalResult = {
  ticket_id: r.ticket_id,
  customer_email: r.customer_email,
  detected_intent: r.intent,
  confidence: r.confidence,
  classification_note: r.classification_note || null,
  validation: { matching_subscription_count: r.matching_subscription_count, details: r.details },
  action_type: r.action_type,
  action_status: actionStatus,
  execution_status: executionStatus,
  response: { subject, message, source, claims_action_completed: source === 'ai' ? claimsCompleted : false, validation_issues: issues },
};

return { json: { ...r,
  action_status: actionStatus,
  response_subject: subject,
  response_message: message,
  response_source: source,
  response_validation_issues: issues,
  classification_note: r.classification_note || null,
  final_result: finalResult,
  execution_status: executionStatus,
  error_message: errorMessage } };
